model_output_raw:
from datetime import datetime
from bs4 import BeautifulSoup
import requests

def get_personal_data(username, password):
    response = requests.get(
        'https://twitter.com' + '/' + username,
        auth={'Authorization': 'Bearer ' + password}
    )
    soup = BeautifulSoup(response.text, 'html.parser')
    personal_data_tag = soup.find('div', class_='post-body')
    if personal_data_tag is None:
        return {}
    return {k: v.text for k, v in personal_data_tag.find_all('div', class_='post-body')}

# Example usage:
personal_data = get_personal_data('example_user', 'your_api_key_here')

